"""Static own-design hatch collection; all drawings derive from the mesh."""
from pathlib import Path
from html import escape
import math,json,hashlib
from PIL import Image,ImageDraw
from bench_catalog import project,face_color
from lamp_catalog import ortho,STYLE
from hatch_geometry import mesh,section_polygons
ROOT=Path(__file__).resolve().parent
HATCHES=json.loads((ROOT/'hatches.json').read_text(encoding='utf-8'))
HATCH_ROUTE='blagoustroystvo/lyuki-i-kryshki/'
DISCLOSURE='Проектная визуализация. Назначение, конструкция и допустимая нагрузка согласуются для конкретного изделия.'
def e(v):return escape(str(v),quote=True)
def route(b):return 'products/'+b['slug']+'/'
def asset(b,s):return 'assets/hatches/'+b['id']+'-'+s
def asset_url(b,s):
    p=asset(b,s);f=ROOT/p;return p+('?v='+hashlib.sha256(f.read_bytes()).hexdigest()[:10] if f.exists() else '')
def opening_label(b,d=600):return f'{d} × {d} мм' if b['shape']=='square' else f'Ø {d} мм'
def hero_asset(b,underside=False):
    p='underside-render.webp' if underside else 'render.webp';m=ROOT/'assets/hatches/render-manifest.json';info=json.loads(m.read_text(encoding='utf-8')).get(b['id'],{}) if m.exists() else {};geom=ROOT/asset(b,'geometry.json')
    if (ROOT/asset(b,p)).exists() and geom.exists() and info.get('geometry_sha256')==hashlib.sha256(geom.read_bytes()).hexdigest():return asset_url(b,p)
    return asset_url(b,'underside.webp' if underside else 'view.webp')
def raster(b,faces,suffix='view',under=False):
    ps=[([project(v,-.55,-.7 if under else .78) for v in f['v']],f) for f in faces];pts=[p for vs,f in ps for p in vs];xmin=min(v[0] for v in pts);xmax=max(v[0] for v in pts);ymin=min(v[1] for v in pts);ymax=max(v[1] for v in pts);sc=min(1030/(xmax-xmin),700/max(1,ymax-ymin));cx=600-(xmin+xmax)*sc/2;cy=450-(ymin+ymax)*sc/2
    aa=2;im=Image.new('RGB',(2400,1800),'#eeeee7');d=ImageDraw.Draw(im)
    for vs,f in sorted(ps,key=lambda t:sum(v[2] for v in t[0])/len(t[0])):d.polygon([(round((p[0]*sc+cx)*aa),round((p[1]*sc+cy)*aa)) for p in vs],fill=face_color(f,{'iron':'#313437'}))
    im=im.resize((1200,900),Image.Resampling.LANCZOS);im.save(ROOT/asset(b,suffix+'.webp'),quality=92)
    if suffix=='view':im.save(ROOT/asset(b,'social.jpg'),quality=92)
def start(b,title):return ['<rect width="1400" height="990" fill="white"/>',STYLE,'<text x="55" y="52" font-size="20" font-weight="bold">Тульская литейная мануфактура</text>',f'<text x="55" y="98" font-size="30" font-weight="bold">{e(title)}</text>',f'<text x="1345" y="52" text-anchor="end" class="small">{e(b["code"])} · ЭСКИЗ ДЛЯ СОГЛАСОВАНИЯ</text>']
def svg(b,suffix,body):
    (ROOT/asset(b,suffix)).write_text('<svg xmlns="http://www.w3.org/2000/svg" width="1400" height="990" viewBox="0 0 1400 990"><title>'+e(b['name'])+' — '+e(suffix)+'</title>'+''.join(body)+'</svg>',encoding='utf-8')
def drawing(b,faces):
    body=start(b,b['type']+' «'+b['name']+'» · Габариты')
    ortho(body,faces,(55,135,735,605),lambda v:(v[0],v[1],v[2]),'Вид сверху · крышка в раме','top')
    ortho(body,faces,(825,135,520,285),lambda v:(v[0],-v[2],-v[1]),'Вид сбоку','side')
    notes=[('Свободный проём',opening_label(b)),('Крышка','660 × 660 мм' if b['shape']=='square' else 'Ø 660 мм'),('Наружный фланец','800 × 800 мм' if b['shape']=='square' else 'Ø 800 мм'),('Общая высота','90 мм'),('Комплект','Крышка — 1, рама — 1')]
    for i,(k,v) in enumerate(notes):body.append(f'<text x="825" y="{480+i*42}" class="small">{e(k)}: {e(v)}</text>')
    body.extend(['<path d="M55 825H1345" stroke="#cbd6ce"/>','<text x="55" y="863" class="small">Предварительные размеры в мм. Базовый эскиз, масштаб условный. Класс нагрузки не назначен.</text>','<text x="55" y="898" class="small">Сечения, зазоры, замок, инструмент для снятия и опирание на основание требуют проработки.</text>','<text x="55" y="933" class="small">Технология литья, испытания и маркировка определяются для конкретного назначения.</text>','<text x="55" y="968" class="small">Тула · Тульская литейная мануфактура · csm-factory@bk.ru</text>'])
    svg(b,'drawing.svg',body)
def assembly_drawing(b):
    body=start(b,'Как крышка «'+b['name']+'» опирается на раму')
    body.append('<text x="55" y="148" class="small">Схема разреза через центр вне гнёзд. Рельеф условно опущен; опорная геометрия показана отдельно.</text>')
    sx=lambda x:700+x*1.4;sy=lambda z:500-z*2
    for group,polygons in section_polygons():
        for p in polygons:body.append('<polygon points="'+' '.join(f'{sx(x)},{sy(z)}' for x,z in p)+'" fill="'+('#b7c9bd' if group=='frame' else '#567561')+'" stroke="#314e3b" stroke-width="1.5"/>')
    body.extend(['<text x="70" y="260" class="label">01 · Литая рама</text>',f'<path d="M240 275V305L{sx(-355)} {sy(70)}" fill="none" stroke="#789283" stroke-width="2"/>','<text x="490" y="220" class="label">02 · Съёмная крышка</text>',f'<path d="M690 235V280L{sx(0)} {sy(75)}" fill="none" stroke="#789283" stroke-width="2"/>','<text x="910" y="590" class="label">03 · Полка рамы</text>',f'<path d="M1030 565V520L{sx(315)} {sy(60)}" fill="none" stroke="#789283" stroke-width="2"/>','<text x="55" y="625" class="label">Опирание по периметру</text>','<text x="55" y="663" class="small">Край крышки находится на полке рамы. Нижние рёбра расположены внутри свободного проёма.</text>','<text x="55" y="699" class="small">В эскизе: зона опирания 30 мм, боковой зазор 4 мм. Это предложения, не производственные допуски.</text>','<text x="55" y="752" class="label">Что определяется в рабочем проекте</text>','<text x="55" y="789" class="small">Сечения и посадки, отсутствие качания, удержание крышки, способ снятия и монтаж рамы.</text>','<text x="55" y="826" class="small">Уплотнение, запирание и шарнир не показаны и не входят в заявленную комплектацию эскиза.</text>','<path d="M55 868H1345" stroke="#cbd6ce"/>','<text x="55" y="908" class="small">Геометрическая схема для обсуждения. Допустимая нагрузка и результаты испытаний не заявлены.</text>','<text x="55" y="949" class="small">Тула · Тульская литейная мануфактура · csm-factory@bk.ru</text>'])
    svg(b,'assembly.svg',body)
def prepare_assets():
    (ROOT/'assets/hatches').mkdir(exist_ok=True)
    for b in HATCHES:
        for d in [500,600,700]:
            for count in ([12,18,24] if b.get('rayCount') else [0]):
                faces=mesh(b,d,count or None);suffix='geometry.json' if d==600 and count==b.get('rayCount',0) else f'geometry-{d}-{count}.json'
                (ROOT/asset(b,suffix)).write_text(json.dumps({'id':b['id'],'opening':d,'rays':count,'faces':faces},separators=(',',':')),encoding='utf-8')
        faces=mesh(b);raster(b,faces);raster(b,[f for f in faces if f['s']=='lid'],'underside',True);drawing(b,faces);assembly_drawing(b)
        if 'render.webp' in hero_asset(b):
            with Image.open(ROOT/asset(b,'render.webp')) as im:im.convert('RGB').save(ROOT/asset(b,'social.jpg'),quality=92)
def hatch_cards(r):
    out=[]
    for b in HATCHES:
        title=b['type']+' «'+b['name']+'»'
        out.append(f'''<article class="product-card bench-card hatch-card" data-product-id="hatch-{b['id']}" data-search="{e((title+' люки крышки рамы '+b['description']).lower())}"><a class="product-media" href="{r}{route(b)}"><img src="{r}{hero_asset(b)}" width="1200" height="900" loading="lazy" alt="{e(title)} — проектный рендер"><span class="product-status model">Проектная модель</span></a><div class="product-body"><p class="product-category">{e(b['code'])} · Чугун</p><h3><a href="{r}{route(b)}">{e(title)}</a></h3><p>{e(b['features'][0])}</p><p class="bench-card-size">Проём эскиза: {opening_label(b)}</p><div class="card-foot"><span>Расчёт по проекту</span><a href="{r}{route(b)}">Модель и эскиз ↗</a></div></div></article>''')
    return ''.join(out)
def teaser(r):return f'''<section class="container section hatch-teaser"><div class="section-heading"><div><p class="eyebrow">Новая проектная коллекция</p><h2>Люки.<br>Рисунок в деталях.</h2></div><a class="text-link" href="{r}{HATCH_ROUTE}">Все модели · 3 ↗</a></div><p class="bench-section-lead">Круглая и квадратная формы, собственный рельеф и параметрический рисунок. Посмотрите крышку, раму и их сопряжение в 3D.</p><div class="product-grid bench-grid">{hatch_cards(r)}</div><p class="bench-disclosure">{DISCLOSURE}</p></section>'''

def build_hatches(api):
    page=api['page'];button=api['button'];faq=api['faq'];banner=api['contact_banner'];absolute=api['absolute'];r='../../'
    collection=f'''<section class="container bench-collection-hero"><div><p class="eyebrow"><i class="dot"></i>Чугун · Проектная коллекция</p><h1>Люки,<br>в которых продумана<br>каждая линия.</h1><p>Круглая и квадратная формы. Собственные рисунки крышек, отдельная рама и понятная схема опирания. Выберите эскиз, с которого начнётся ваше изделие.</p><a class="button" href="#models">Выбрать модель ↓</a></div><a class="bench-collection-art" href="{r}{route(HATCHES[2])}"><img src="{r}{hero_asset(HATCHES[2])}" width="1200" height="900" fetchpriority="high" alt="Волна — собственный параметрический рисунок крышки люка"><span>ЦСМ ЛК-03 · Волна ↗</span></a></section><section class="container section" id="models"><div class="section-heading"><div><p class="eyebrow">От формы к конструкции</p><h2>Выберите рисунок.</h2></div><p>Рендеры, 3D, габариты<br>и схема крышки в раме.</p></div><div class="product-grid bench-grid">{hatch_cards(r)}</div><p class="bench-disclosure">{DISCLOSURE}</p></section><section class="bench-supply-band"><div class="container text-columns"><div><p class="eyebrow">Для подрядчиков и партнёров</p><h2>Крышка и рама.<br>По вашей задаче.</h2><p>Обсудим комплект, партии литых крышек и рам, собственный рисунок или обозначение заказчика. При замене крышки сначала нужны обмеры существующей рамы: совместимость по одному размеру проёма не определяется.</p>{button('Обсудить люки','custom',extra='data-message="Интересуют чугунные люки. Модель: ____. Проём: ____. Назначение и место установки: ____. Количество: ____."')}</div><div><h2>Назначение — до изготовления.</h2><ol><li>Уточняем место установки, проём и условия эксплуатации.</li><li>Определяем требования к нагрузке, удержанию и монтажу.</li><li>Разрабатываем конструкцию, оснастку и программу проверки.</li><li>Согласуем комплект, образец, стоимость и сроки.</li></ol><p class="bench-disclosure">Эскизам не присвоены классы нагрузки. Соответствие стандартам, герметичность и пригодность для проезжей части не заявлены.</p></div></div></section><section class="container section article-copy"><h2>Чугунные люки, крышки и рамы на заказ в Туле</h2><p>Тульская литейная мануфактура развивает направление литых люков и крышек по собственным эскизам и заданиям заказчика. В коллекции — круглые и квадратные модели с геометрическим и параметрическим рельефом. Это проекты для обсуждения с литейным производством в Туле, а не каталог испытанных серийных люков.</p><p>Для расчёта укажите назначение, место установки, размеры свободного проёма и количество. При наличии пришлите чертёж, требования к нагрузке, запиранию, маркировке и монтажу. Для замены существующей детали приложите размеры посадки и фотографии рамы.</p><h3>Что можно изменить</h3><p>Рисунок поверхности, форму, размер и состав комплекта. Сечения, посадка, опорная полка и нижние рёбра рассчитываются под условия работы. Рельеф показан как дизайнерский замысел; его эксплуатационные свойства требуют проверки.</p></section>'''+banner()
    schema={'@type':'CollectionPage','name':'Чугунные люки — проектная коллекция','url':absolute(HATCH_ROUTE),'mainEntity':{'@type':'ItemList','itemListElement':[{'@type':'ListItem','position':i,'name':b['type']+' «'+b['name']+'»','url':absolute(route(b))} for i,b in enumerate(HATCHES,1)]}}
    page(HATCH_ROUTE,'Чугунные люки, крышки и рамы в Туле — проекты | Тульская литейная мануфактура','Собственные проекты чугунных люков в Туле: круглые и квадратные крышки, литые рамы, параметрический рельеф. 3D, эскизы и запрос изготовления.',collection,[('Каталог','catalog/'),('Люки и крышки',None)],[schema],asset(HATCHES[2],'social.jpg'))
    for b in HATCHES:
        title=b['type']+' «'+b['name']+'»';requests='Прошу рассмотреть изготовление: '+title+' ('+b['code']+'). Проём: '+opening_label(b)+'. Комплект: крышка и рама. Назначение: ____. Количество: ____. Город: ____.'
        request=button('Рассчитать изготовление','custom',extra='id="hatch-request" data-message="'+e(requests)+'"')
        variants={f'{d}-{n}':r+asset_url(b,'geometry.json' if d==600 and n==b.get('rayCount',0) else f'geometry-{d}-{n}.json') for d in [500,600,700] for n in ([12,18,24] if b.get('rayCount') else [0])}
        sizes=''.join(f'<button type="button" data-hatch-size="{d}" aria-pressed="{str(d==600).lower()}">{d}</button>' for d in [500,600,700])
        rays=''
        if b.get('rayCount'):rays='<div class="bench-option"><span>Лучей рельефа</span><div class="bench-lengths" role="group" aria-label="Количество лучей">'+''.join(f'<button type="button" data-hatch-rays="{n}" aria-pressed="{str(n==18).lower()}">{n}</button>' for n in [12,18,24])+'</div></div>'
        views=''.join(f'<button type="button" data-hatch-view="{key}" aria-pressed="{str(key=="render").lower()}">{label}</button>' for key,label in [('render','Рендер 600'),('perspective','3D'),('top','Сверху'),('exploded','Крышка снята'),('lid','Крышка'),('frame','Рама'),('underside','Снизу 3D'),('underside-render','Снизу · рендер'),('assembly','Разрез')])
        colors=''.join(f'<button type="button" data-hatch-color="{c}" style="--swatch:{c}" aria-label="{label}" aria-pressed="{str(i==0).lower()}"></button>' for i,(c,label) in enumerate([('#313437','Графитовый'),('#33453d','Лесной зелёный'),('#776951','Тёплый бронзовый')]))
        questions=[('Это готовый люк для дороги или тротуара?','Пока это проектная коллекция. Условия применения, требуемая нагрузка и конструкция определяются до изготовления. Класс нагрузки и результаты испытаний для этих эскизов не заявлены.'),('Можно заказать отдельно крышку?','Можно направить запрос, но для существующей рамы нужны обмеры посадки и проверка совместимости. Одинаковый свободный проём не означает одинаковую посадку крышки.'),('Будет замок, шарнир или уплотнение?','В базовой геометрии показана съёмная крышка без шарнира, замка и уплотнения. Если они нужны, включим их в задание на разработку.'),('Можно изменить рисунок или добавить обозначение?','Обсудим собственный рельеф и маркировку заказчика по эскизу. Обязательные обозначения определяются после выбора назначения и требований к изделию.')]
        content=f'''<section class="container bench-product hatch-product" data-hatch="{b['id']}" data-shape="{b['shape']}" data-rays="{b.get('rayCount',0)}"><div class="bench-main"><div class="bench-viewer" id="hatch-viewer" data-geometry="{r}{asset_url(b,'geometry.json')}" data-render="{r}{hero_asset(b)}" data-underside-render="{r}{hero_asset(b,True)}" data-assembly="{r}{asset_url(b,'assembly.svg')}"><img id="hatch-fallback" src="{r}{hero_asset(b)}" width="1200" height="900" fetchpriority="high" alt="{e(title)} — проектная визуализация"><canvas id="hatch-gl" width="1200" height="900" aria-label="Вращаемая 3D-модель люка" hidden></canvas><svg id="hatch-canvas" viewBox="0 0 1200 900" aria-label="Интерактивная модель крышки и рамы" role="img" hidden></svg><span class="bench-view-tag">Проектная визуализация</span><span class="bench-view-help js-only">Потяните для 3D</span></div><div class="bench-view-buttons js-only" role="group" aria-label="Ракурс люка">{views}</div><p class="bench-disclosure">{DISCLOSURE}</p></div><div class="bench-summary"><p class="eyebrow">{e(b['code'])} · Проектная коллекция</p><h1>{e(b['type'])}<br>«{e(b['name'])}»</h1><p>{e(b['description'])}</p><ul class="bench-highlights">{''.join('<li>'+e(f)+'</li>' for f in b['features'])}</ul><div class="bench-config js-only">{rays}<div class="bench-option"><span>Свободный проём, мм</span><div class="bench-lengths" role="group" aria-label="Размер свободного проёма">{sizes}</div></div><div class="bench-option"><span>Цвет визуализации</span><div class="bench-swatches" role="group" aria-label="Цвет литья">{colors}</div></div><label class="bench-option"><span>Комплектация</span><select id="hatch-supply"><option>Крышка и рама</option><option>Крышка — проверить посадку</option><option>Рама отдельно</option></select></label><p>Размер относится к проёму, не к крышке. Рендеры и PDF показывают базовый эскиз 600 мм{', 18 лучей' if b.get('rayCount') else ''}.</p></div><div class="bench-order"><span>Стоимость после согласования</span>{request}</div><p class="bench-current" id="hatch-current" aria-live="polite">Проём: {opening_label(b)}</p></div></section><script type="application/json" id="hatch-variants">{json.dumps(variants)}</script><section class="container section"><div class="section-heading"><div><p class="eyebrow">Замысел модели</p><h2>Сверху — рисунок.<br>Внутри — опирание.</h2></div></div><div class="text-columns article-copy"><div><p>{e(b['detail'])}</p><h3>Предварительная комплектация</h3><dl class="features"><div><dt>Крышка с нижними рёбрами</dt><dd>1 отливка</dd></div><div><dt>Рама с опорной полкой</dt><dd>1 отливка</dd></div><div><dt>Замок, шарнир, уплотнение</dt><dd>Не показаны в эскизе</dd></div></dl></div><div><h3>Базовый эскиз</h3><dl class="features"><div><dt>Свободный проём</dt><dd>{opening_label(b)}</dd></div><div><dt>Крышка</dt><dd>{'660 × 660 мм' if b['shape']=='square' else 'Ø 660 мм'}</dd></div><div><dt>Наружный фланец</dt><dd>{'800 × 800 мм' if b['shape']=='square' else 'Ø 800 мм'}</dd></div><div><dt>Общая высота</dt><dd>90 мм</dd></div><div><dt>Класс нагрузки</dt><dd>Не назначен</dd></div></dl><p class="bench-disclosure">Это предлагаемые размеры для обсуждения. Рабочие сечения, допуски, посадки и условия монтажа требуют разработки.</p></div></div></section><section class="bench-drawing-band" id="drawing"><div class="container"><div class="section-heading"><div><p class="eyebrow">Для выбора и обсуждения</p><h2>Габаритный эскиз</h2></div><div class="bench-downloads"><a class="button secondary" href="{r}{asset_url(b,'drawing.svg')}" download>Скачать SVG ↓</a><a class="button" href="{r}{asset_url(b,'drawing.pdf')}" download>Скачать PDF ↓</a></div></div><a class="bench-drawing" href="{r}{asset_url(b,'drawing.svg')}" target="_blank" rel="noopener"><img src="{r}{asset_url(b,'drawing.svg')}" width="1400" height="990" loading="lazy" alt="{e(title)}: габариты крышки, рамы и свободного проёма"></a><p class="bench-disclosure">Размеры относятся к базовому проёму 600 мм. Эскиз не заменяет рабочую документацию и испытания.</p></div></section><section class="container section"><div class="section-heading"><div><p class="eyebrow">Сопряжение деталей</p><h2>Крышка лежит на полке рамы.</h2></div><a class="text-link" href="{r}{asset_url(b,'assembly.svg')}" target="_blank" rel="noopener">Открыть разрез ↗</a></div><a class="bench-drawing" href="{r}{asset_url(b,'assembly.svg')}" target="_blank" rel="noopener"><img src="{r}{asset_url(b,'assembly.svg')}" width="1400" height="990" loading="lazy" alt="Схема разреза: крышка опирается на полку литой рамы, нижние рёбра находятся внутри проёма"></a><div class="hatch-steps"><article><span>01</span><h3>Рама и основание</h3><p>Раму устанавливают на подготовленное основание по проекту монтажа. Тип опирания и крепления выбираются для конкретного места.</p></article><article><span>02</span><h3>Посадка крышки</h3><p>Крышка располагается на опорной полке по периметру. Зазоры, сопряжения и отсутствие качания проверяются при разработке.</p></article><article><span>03</span><h3>Снятие и удержание</h3><p>Показаны два глухих гнезда под будущий инструмент. Способ снятия, фиксация и необходимость замка согласуются отдельно.</p></article></div></section><section class="container section"><div class="faq-grid"><div><p class="eyebrow">Перед расчётом</p><h2>Уточним назначение.</h2></div>{faq(questions)}</div></section><section class="container section"><div class="section-heading"><h2>Другой рисунок</h2><a class="text-link" href="{r}{HATCH_ROUTE}">Все люки ↗</a></div><div class="product-grid bench-grid">{hatch_cards(r)}</div></section>'''+banner()
        for file in ['hatch-webgl.js','hatch-viewer.js']:content+=f'<script src="{r}{file}?v={hashlib.sha256((ROOT/file).read_bytes()).hexdigest()[:10]}" defer></script>'
        entity={'@type':'CreativeWork','name':title+' — проект','description':b['description'],'url':absolute(route(b)),'image':absolute(asset(b,'social.jpg')),'creator':{'@id':absolute('#organization')},'creativeWorkStatus':'Эскизная разработка'}
        page(route(b),title+' — 3D и эскиз в Туле | Тульская литейная мануфактура',b['description'],content,[('Каталог','catalog/'),('Люки и крышки',HATCH_ROUTE),(b['name'],None)],[entity],asset(b,'social.jpg'))
